ALTER TABLE "admin_users" ADD COLUMN "mailbox" varchar(254) GENERATED ALWAYS AS (case when split_part(lower("admin_users"."email"), '@', 2) in ('gmail.com', 'googlemail.com') then replace(coalesce(nullif(split_part(split_part(lower("admin_users"."email"), '@', 1), '+', 1), ''), split_part(lower("admin_users"."email"), '@', 1)), '.', '') || '@' || 'gmail.com' else coalesce(nullif(split_part(split_part(lower("admin_users"."email"), '@', 1), '+', 1), ''), split_part(lower("admin_users"."email"), '@', 1)) || '@' || split_part(lower("admin_users"."email"), '@', 2) end) STORED NOT NULL;--> statement-breakpoint
CREATE INDEX "admin_users_mailbox_idx" ON "admin_users" USING btree ("mailbox");